lesson.code:
type Tarefa struct {
	ID    int
	Valor int
}

type Processador interface {
	Processar(t Tarefa) (int, error)
}

func executar(tarefas []Tarefa, p Processador) []int {
	resultados := make(chan int, len(tarefas))
	var wg sync.WaitGroup

	for _, t := range tarefas {
		wg.Add(1)
		go func(t Tarefa) {
			defer wg.Done()
			if r, err := p.Processar(t); err == nil {
				resultados <- r
			}
		}(t)
	}

	wg.Wait()
	close(resultados)

	var saida []int
	for r := range resultados {
		saida = append(saida, r)
	}
	return saida
}

